import pages
P_=[('overview','Pradoṣa','Śiva’s Twilight, Twice a Month'),('nilakantha','Nīlakaṇṭha','The Poison, the Blue Throat and the Dance on Nandi'),('vrata-katha','The Pradoṣa Vrata Kathā','Śāṇḍilya, the Widow and the Two Boys'),('pradosha-stotram','The Pradoṣa Stotrāṣṭakam','The Hymn of the Twilight Hour'),('keeping-the-vow','Keeping the Pradoṣa Vow','The Fast, the Hour and the Worship'),('weekday-pradoshas','The Seven Pradoṣas','Soma, Bhauma, Śani and the Rest'),('in-temples','Pradoṣa in Temples','Nandi, the Crescent Path and the Procession'),('masa-shivaratri','Māsa Śivarātri','The Night After Pradoṣa')]
