LING='<path d="M-34 0 h68 l-8 -12 h-52z" fill="#8a8f9a"/><path d="M-30 -12 h60 q10 0 14 6 l-8 4" fill="#8a8f9a"/><path d="M-14 -12 v-38 q14 -16 28 0 v38z" fill="#3a3a40"/>'
def dusk(h=190): return f'<rect width="560" height="{h}" fill="#e8a87c"/><rect width="560" height="{int(h*.42)}" fill="#5a5a8a"/>'
SH=lambda: shiva()
R=reading
def bilva(): return ''.join(f'<ellipse cx="{x}" cy="{y}" rx="7" ry="13" fill="#3a8a3a" stroke="#111" stroke-width="1.5" transform="rotate({r} {x} {y})"/>' for x,y,r in [(-10,-8,-30),(0,-14,0),(10,-8,30)])+'<path d="M0 0 v8" stroke="#3a6a2a" stroke-width="2"/>'
def rud(): return ''.join(f'<circle cx="{14*math.cos(a/10*6.283):.1f}" cy="{14*math.sin(a/10*6.283)-4:.1f}" r="3.4" fill="#7a3a1a" stroke-width="1"/>' for a in range(10))
# ================= 5 keeping
i=4
COV=covart('A devotee bathing a liṅga with milk at dusk, with bilva leaves, vibhūti, a rudrākṣa mālā and a lamp',dusk(196).replace('560','440')+g(220,190,1.4,LING)+'<path d="M240 90 q-10 20 -16 40" stroke="#fff" stroke-width="5" fill="none"/>'+g(110,190,1,bilva())+g(340,180,1,rud())+g(380,190,1.2,lamp()))
pp=[foreword(i,['How is Pradoṣa kept? The core is simple: a fast through the day, a bath before sunset, worship of Śiva (and Nandi) in the twilight hour, the hymn and the story, and the fast broken after. Families and temples add their own details.','This part walks through it step by step. It describes common practice; your family tradition and teacher come first, and health comes before any fast.'],[('z','Do I have to fast the whole day?'),('b','Many do; many eat once, or just fruit; some only skip the evening meal until after worship. Choose what you can keep.')]),
 glance([('Day','Trayodaśī prevailing at sunset (check your pañcāṅga)'),('Fast','From sunrise until after the evening worship; levels vary'),('Before sunset','Bath; fresh clothes; vibhūti, rudrākṣa'),('The hour','Pradoṣa kāla around sunset'),('Worship','Nandi, then the liṅga: abhiṣeka, bilva, lamps, hymns'),('Then','The kathā, ārati, prasāda'),('Breaking','After the worship, with simple food')],svg(560,140,'Three steps: fast, worship at dusk, break the fast',''.join(f'<rect x="{40+k*170}" y="30" width="140" height="70" rx="10" fill="{c}" stroke="#111" stroke-width="2"/>'+lab(110+k*170,72,t,12) for k,(c,t) in enumerate([('#fff3cf','fast by day'),('#e8a87c','worship at dusk'),('#cfe0b8','break the fast')])))),
 R('hour','FINDING THE HOUR','Pradoṣa kāla',svg(560,150,'A clock-like arc showing the time window around sunset',dusk(150)+'<path d="M80 130 q200 -120 400 0" fill="none" stroke="#fff" stroke-width="3"/>'+g(280,60,1,sun(16))+'<path d="M200 130 L360 130" stroke="#c0392b" stroke-width="8"/>'+lab(280,148,'pradoṣa kāla')),['<b>The window.</b> Pradoṣa kāla is the twilight around sunset. Sources define it differently: about 1½ hours before and after sunset, or roughly the first 90 minutes after sunset, or two ghaṭikās (48 minutes) either side.','<b>Local sunset.</b> Since sunset changes by place and season, the window does too. Almanacs and temple calendars give the local time.','<b>The day.</b> Pradoṣa is kept on the day Trayodaśī prevails at sunset, even if it began the previous evening.','<b>Practical.</b> Aim to be at worship from a little before sunset until it is dark.'],[('z','What if I’m stuck at work at sunset?'),('b','Do the worship as soon as you can after; many temples hold it for a while. Sincerity first.')],'Be with Śiva <b>from sunset into dark</b>.'),
 R('fast','THE FAST','Levels and sense',svg(560,150,'Four plates from empty to a simple fruit plate',''.join(g(90+k*125,120,1,o) for k,o in enumerate(['<ellipse rx="40" ry="10" fill="#fff" stroke="#111"/>','<rect x="-14" y="-30" width="28" height="30" fill="#fff" stroke="#111" stroke-width="2"/><rect x="-12" y="-16" width="24" height="14" fill="#8fb8de"/>',pot('#f08a24'),'<ellipse rx="40" ry="10" fill="#e8c06a" stroke="#111"/>']))+''.join(lab(90+k*125,145,t) for k,t in enumerate(['full fast','water','fruit, milk','one simple meal']))),['<b>Full fast.</b> Some keep no food from sunrise until after the Pradoṣa worship.','<b>Lighter fasts.</b> Water, fruit and milk; or one simple meal at midday; or simply no food after noon until worship.','<b>Food that day.</b> Many avoid grains, onion and garlic on Pradoṣa; customs vary.','<b>Health.</b> The elderly, sick, pregnant and children are traditionally excused. Anyone with diabetes or on medication should follow their doctor, not a custom.'],[('z','Can I keep Pradoṣa without fasting at all?'),('b','Yes. The worship at twilight is the heart of it. The fast is a support.')],'Fast <b>as you can</b>; worship at twilight <b>without fail</b>.'),
 R('prepare','BEFORE SUNSET','Bath, clothes and marks',svg(560,160,'A devotee after bathing, with three lines of vibhūti on the forehead and a rudrākṣa mālā',g(240,150,1.4,person('#f4f1ea'))+'<path d="M228 72 h24 M228 76 h24 M228 80 h24" stroke="#fff" stroke-width="2"/>'+g(380,110,1.6,rud())),['<b>Bath.</b> A bath shortly before sunset prepares the body and mind.','<b>Clean clothes.</b> Fresh or washed clothes; white or simple colours are common.','<b>Vibhūti.</b> Śaivas apply sacred ash (bhasma) in three horizontal lines (tripuṇḍra) on the forehead and arms.','<b>Rudrākṣa.</b> Many wear a rudrākṣa mālā, Śiva’s sacred bead, for the worship and japa.'],[('z','Why ash?'),('b','It reminds us that all things end in ash, and only Śiva remains. Śaivas wear it as their sign.')],'Bathed, marked with ash, <b>ready for twilight</b>.'),
 story('puja','THE EVENING WORSHIP','A simple order',strip('Three panels: worshipping Nandi; bathing the liṅga with milk; offering bilva leaves and a lamp',[panel([(NANDI(),.9)],'#e8a87c',150),panel([(LING,1.1),('<path d="M10 -90 q-6 20 -8 40" stroke="#fff" stroke-width="4" fill="none"/>',1)],'#5a5a8a',150),panel([(LING,1),(bilva(),1),(lamp(),.8)],'#fff3cf',150)],['Nandi first','abhiṣeka','bilva and lamp']),'At home or in a temple, the twilight worship often runs like this:',['<b>Gaṇeśa, then Nandi.</b> A prayer to Gaṇeśa; then Nandi is worshipped (in temples, bathed).','<b>Abhiṣeka.</b> The liṅga is bathed with water, milk, curd, honey, ghee, sugar, tender coconut and sandal, as available, with the Pañcākṣara “namaḥ śivāya” or the Śrī Rudram.','<b>Bilva and flowers.</b> Bilva (bael) leaves, three-lobed, are offered, with white flowers, vibhūti and sandal.','<b>Hymns and story.</b> The <a href="/festivals/pradosha/pradosha-stotram/">Pradoṣa hymn</a>, other Śiva hymns, and the <a href="/festivals/pradosha/vrata-katha/">vrata kathā</a>.','<b>Lamp and ārati.</b> Lamps are offered and ārati performed; prasāda is shared.'],[('z','Do I need a liṅga at home?'),('b','A picture of Śiva, or a small liṅga, or simply a lamp. Many families just go to the temple.')],'Nandi, abhiṣeka, bilva, hymn, story, <b>ārati</b>.'),
 R('offerings','WHAT IS OFFERED','Bilva, milk and more',svg(560,160,'Bilva leaves, a pot of milk, a lamp, white flowers and vibhūti',g(80,130,1.5,bilva())+g(190,130,1.2,pot('#fff'))+g(300,130,1.4,lamp())+g(410,130,1.1,lotus('#fff','#f4f1ea'))+g(500,130,1,'<ellipse rx="20" ry="8" fill="#e8e8e8" stroke="#111"/>')),['<b>Bilva.</b> The three-lobed bilva leaf is Śiva’s favourite offering; see our <a href="/shiva/bilvashtakam/">Bilvāṣṭakam</a>.','<b>Milk and water.</b> Abhiṣeka with milk and water cools the poison-drinking Lord, devotees say.','<b>White flowers and vibhūti.</b> Jasmine and other white flowers; sacred ash.','<b>Food.</b> Simple naivedya: fruit, cooked rice with jaggery, or sweets per custom, later shared.'],[('z','Why does Śiva like bilva?'),('b','Tradition says the three leaves are his three eyes, or the three guṇas. And it grows wild: the simple god loves simple things.')],'Bilva, milk, white flowers, ash: <b>Śiva’s offerings</b>.'),
 R('chant','WHAT TO CHANT','Names and hymns',svg(560,150,'A rosary and an open book',g(200,110,1.8,rud())+g(380,110,1.8,book())),['<b>Pañcākṣara.</b> “Namaḥ śivāya”, the five-syllable mantra, repeated with a rudrākṣa mālā; see our <a href="/shiva/shiva-panchakshara-stotram/">Pañcākṣara Stotram</a>.','<b>Mahāmṛtyuñjaya.</b> The great death-conquering mantra; see <a href="/shiva/mahamrityunjaya-mantra/">our article</a>.','<b>Rudram.</b> Those trained chant the <a href="/shiva/sri-rudram/">Śrī Rudram</a> during abhiṣeka.','<b>Pradoṣa hymn.</b> The Skanda Purāṇa’s <a href="/festivals/pradosha/pradosha-stotram/">Pradoṣa Stotrāṣṭakam</a>.'],[('z','Which one is best?'),('b','The one you can say with attention. “Namaḥ śivāya” said sincerely is complete.')],'<b>Namaḥ śivāya</b> at twilight.'),
 R('breaking','BREAKING THE FAST','After the worship',svg(560,150,'A simple plate of food after the evening worship, with a lamp',g(240,120,1.5,'<ellipse rx="50" ry="12" fill="#5a8a3a" stroke="#111"/>'+''.join(f'<circle cx="{x}" cy="-6" r="7" fill="#fff"/>' for x in (-20,0,20)))+g(400,130,1.4,lamp())),['<b>After ārati.</b> The fast is broken after the evening worship, beginning with prasāda.','<b>Simple food.</b> A light, simple meal, often without onion and garlic.','<b>Feeding others.</b> Feeding a guest or someone in need is praised.','<b>Next day.</b> Some continue into Māsa Śivarātri on Caturdaśī ('+L(7,'Part 8')+').'],[('z','Can I eat anything after?'),('b','Something light and pure. You’ve just sat with Śiva; don’t rush to a feast.')],'Prasāda first, <b>then a simple meal</b>.'),
 R('regular','MAKING IT A HABIT','Pradoṣa through the year',svg(560,150,'A calendar with two marks each month',''.join(f'<rect x="{40+k*40}" y="40" width="34" height="70" rx="4" fill="#fff" stroke="#111" stroke-width="1.5"/><circle cx="{57+k*40}" cy="60" r="5" fill="#5a5a8a"/><circle cx="{57+k*40}" cy="90" r="5" fill="#e8a87c"/>' for k in range(12))),['<b>Twice a month.</b> About 24 Pradoṣas a year; many devotees keep all, others only the dark-fortnight one, or the Saturdays.','<b>A vow for a period.</b> Some take a vow for a set number of Pradoṣas (for example 11 or 24), often begun on a Śani Pradoṣa.','<b>Completion.</b> Such vows are completed with an udyāpana, a closing worship and feeding.','<b>The real goal.</b> A steady habit of meeting Śiva at twilight.'],[('z','Can I start any time?'),('b','Any Trayodaśī. Many like to start on a Monday or Saturday Pradoṣa.')],'Twice a month, <b>a meeting with Śiva</b>.'),
 end(i,['<b>Day.</b> Trayodaśī at sunset.','<b>Fast.</b> As you can, until after worship.','<b>Prepare.</b> Bath, clean clothes, vibhūti, rudrākṣa.','<b>Worship.</b> Nandi, abhiṣeka, bilva, hymns, kathā, ārati.','<b>Break.</b> Prasāda, then a simple meal.'],'Part 6 looks at the seven weekday Pradoṣas: why a Monday or Saturday Pradoṣa is special.','Keeping the vow'),
 sources([('Practice:','Wikipedia, “Pradosha” (vrata, bath before sunset, worship, kathā); temple and household practice as commonly described.')],'definitions of pradoṣa kāla; foods avoided; vow lengths (vary).','General guidance; follow your teacher and doctor.')]
build(i,'PART 5 OF 8 · THE FAST · THE HOUR · THE WORSHIP',COV,'Bilva, milk and a lamp at dusk','Finding <b>the hour</b>, the <b>fast</b>, preparing <b>before sunset</b>, the <b>evening worship</b> step by step, what to offer and chant, and <b>breaking the fast</b>.','How to keep the Pradoṣa vow: the pradoṣa kāla, fasting levels, preparing before sunset, the evening worship of Nandi and the liṅga, bilva and abhiṣeka, what to chant, breaking the fast and keeping it through the year. Part 5 of the illustrated Pradoṣa series.',pp)
# ================= 6 weekdays
i=5
DAYS=[('ravi','RAVI PRADOṢA','Sunday',sun(20),'The Sun’s day. A Pradoṣa on Sunday is prayed on for health and vigour, joining Śiva’s grace with the Sun’s. Popular vrata books give it its own story of a devotee’s illness cured.','health'),
 ('soma','SOMA PRADOṢA','Monday',moon(),'The Moon’s day, and Monday is already Śiva’s, since he wears the moon. Soma Pradoṣa is one of the two most prized. Many recall the moon’s own cure by Śiva.','peace of mind, the fulfilment of wishes'),
 ('bhauma','BHAUMA PRADOṢA','Tuesday','<circle r="20" fill="#c0392b" stroke="#111" stroke-width="2"/>','Mars’s day (Bhauma, Maṅgala). A Tuesday Pradoṣa is prayed on for relief from debts and illness, and for strength; some also worship Hanumān.','relief from debt and illness'),
 ('budha','BUDHA PRADOṢA','Wednesday','<circle r="20" fill="#2a9d6f" stroke="#111" stroke-width="2"/>','Mercury’s day. Wednesday Pradoṣa is prayed on for intelligence, learning and success in work.','learning, success'),
 ('guru','GURU PRADOṢA','Thursday','<circle r="20" fill="#e0a800" stroke="#111" stroke-width="2"/>','Jupiter’s day, the guru’s day. Thursday Pradoṣa is prayed on for wisdom, for one’s teacher, and against enemies; Dakṣiṇāmūrti is often worshipped.','wisdom, the guru’s grace'),
 ('shukra','ŚUKRA PRADOṢA','Friday','<circle r="20" fill="#fff" stroke="#111" stroke-width="2"/>','Venus’s day. Friday Pradoṣa is prayed on for marital harmony, prosperity and good fortune.','harmony, prosperity'),
 ('shani','ŚANI PRADOṢA','Saturday','<circle r="20" fill="#2a2a3a" stroke="#111" stroke-width="2"/>','Saturn’s day. Śani Pradoṣa is the most prized of all, often called Mahā Pradoṣa. Those under a hard Saturn period (sāḍe-sāti) traditionally keep it, since Śiva is said to be Saturn’s own guru.','release from Saturn’s afflictions, great merit')]
COV=covart('Seven small planetary discs in a row, sun, moon, red Mars, green Mercury, golden Jupiter, white Venus and dark Saturn, above a liṅga at dusk, with Saturn circled',dusk(196).replace('560','440')+''.join(g(40+k*60,60,.9,d[3]) for k,d in enumerate(DAYS))+'<circle cx="400" cy="60" r="28" fill="none" stroke="#c0392b" stroke-width="3"/>'+g(220,190,1.3,LING))
pp=[foreword(i,['A Pradoṣa takes extra colour from the weekday it falls on. Each day of the week belongs to a planet (graha), and tradition gives each weekday Pradoṣa its own fruit. Two stand out: <b>Soma Pradoṣa</b> (Monday) and above all <b>Śani Pradoṣa</b> (Saturday).','This part goes through all seven. The fruits listed are those of popular tradition and vrata books, not of a single scripture; we say so plainly.'],[('z','Why does the weekday matter?'),('b','Two sacred times overlapping: Śiva’s twilight and a planet’s day. Devotees pray for what that planet rules.')]),
 glance([(d[2],d[1].title().replace('Pradoṣa','Pradoṣa')+': '+d[5]) for d in DAYS],svg(560,120,'Seven planetary discs',''.join(g(50+k*77,60,1,d[3]) for k,d in enumerate(DAYS))+''.join(lab(50+k*77,110,d[2][:3]) for k,d in enumerate(DAYS)))),
 R('types','KINDS OF PRADOṢA','Daily, fortnightly, monthly, great',svg(560,140,'Four nested circles labelled daily, fortnightly, monthly and great',''.join(f'<circle cx="280" cy="70" r="{60-k*14}" fill="{c}" stroke="#111" stroke-width="2"/>' for k,c in enumerate(['#e3eaf3','#cfd8e6','#e8a87c','#5a5a8a']))),['<b>Nitya.</b> Some traditions count every twilight as a daily (nitya) Pradoṣa.','<b>Pakṣa.</b> Every Trayodaśī twilight: the fortnightly Pradoṣa, the usual vow.','<b>Māsa.</b> Some count the dark-fortnight Trayodaśī as the monthly Pradoṣa, leading into Māsa Śivarātri.','<b>Mahā.</b> A Pradoṣa falling on Saturday is called <b>Mahā Pradoṣa</b>; some lists add a <i>pralaya</i> Pradoṣa, the twilight at the end of time when all returns to Śiva.'],[('z','Every evening is a little Pradoṣa?'),('b','In that sense, yes. Trayodaśī is the big one, Saturday the biggest.')],'Daily, fortnightly, monthly, <b>great</b>.')]
for key,t,day,disc,txt_,fruit in DAYS:
    pp.append(R(key,t,f'Pradoṣa on a {day}',svg(560,160,f'The disc of the {day} planet above a liṅga at dusk',dusk(160)+g(160,70,1.6,disc)+g(360,150,1.3,LING)+lab(160,130,day)),[f'<b>The day.</b> {txt_}',f'<b>Prayed for.</b> In popular tradition: {fruit}.',f'<b>How.</b> The same worship as every Pradoṣa ('+L(4,'Part 5')+'), with special attention on '+day+'s; some add prayers to the day’s planet.','<b>Read honestly.</b> These associations come from vrata books and astrological practice; the scriptural core is the same for every Pradoṣa.'],[('z',f'Is {day} Pradoṣa better than others?'),('b','Saturday is counted greatest, Monday next. But every Pradoṣa kept sincerely is complete.' if key not in ('shani','soma') else ('The greatest of all, by tradition. Śiva is Saturn’s guru; at his twilight on Saturn’s day, Saturn himself is said to bow.' if key=='shani' else 'Śiva’s own weekday at Śiva’s own hour. Many begin their Pradoṣa vow on a Monday.'))],f'{day} Pradoṣa: <b>{fruit}</b>.'))
pp+=[end(i,['<b>Weekdays.</b> Each Pradoṣa takes colour from its day’s planet.','<b>Soma.</b> Monday: Śiva’s own day, much prized.','<b>Śani.</b> Saturday: Mahā Pradoṣa, the greatest.','<b>Kinds.</b> Daily, fortnightly, monthly, great.','<b>Core.</b> The same worship every time.'],'Part 7 goes into the temple: Nandi’s abhiṣeka, the crescent-shaped circuit and the procession.','The seven Pradoṣas'),
 sources([('Types:','Wikipedia, “Pradosha” (Śani and Soma Pradoṣa); popular sources on nitya, pakṣa, māsa, mahā and pralaya Pradoṣa; astrological practice on Saturn.')],'weekday fruits (popular vrata books, vary); Śiva as Saturn’s guru (popular tradition).','Popular associations marked as such.')]
build(i,'PART 6 OF 8 · SEVEN DAYS · ŚANI PRADOṢA',COV,'Seven planets, one twilight','The <b>kinds of Pradoṣa</b>, then each <b>weekday Pradoṣa</b> from Sunday to <b>Śani Pradoṣa</b>, with what tradition says each brings.','The seven weekday Pradoṣas: Ravi, Soma, Bhauma, Budha, Guru, Śukra and Śani Pradoṣa (Mahā Pradoṣa), with the kinds of Pradoṣa and their traditional fruits. Part 6 of the illustrated Pradoṣa series.',pp)
# ================= 7 temples
i=6
def somasutra():
    o='<rect x="-160" y="-110" width="320" height="220" rx="10" fill="#f3e3c3" stroke="#111" stroke-width="2"/>'
    o+='<rect x="-40" y="-50" width="80" height="80" fill="#e8c06a" stroke="#111" stroke-width="2"/>'+'<g transform="translate(0 -6) scale(.6)">'+LING+'</g>'
    o+='<path d="M40 -10 h40" stroke="#5a8ac0" stroke-width="4"/><circle cx="84" cy="-10" r="5" fill="#5a8ac0"/>'
    o+='<g transform="translate(0 90) scale(.4)">'+beast('bull','#f4f1ea')+'</g>'
    o+='<path d="M0 70 q-120 0 -120 -80 q0 -70 120 -70 q80 0 80 60" fill="none" stroke="#c0392b" stroke-width="3" stroke-dasharray="6 4"/>'
    return o
COV=covart('A temple plan with Nandi facing the sanctum, the water-spout on the north side, and a dotted crescent-shaped path showing the somasūtra circuit',g(220,110,.6,somasutra()))
pp=[foreword(i,['Pradoṣa is most alive in temples. At twilight on Trayodaśī, Śiva temples across South India are packed: Nandi is bathed first, the liṅga receives a long abhiṣeka, devotees walk an unusual back-and-forth circuit, and the festival image of Śiva and Pārvatī rides out on Nandi.','This part explains what you will see, and why.'],[('z','Why is it so crowded?'),('b','Because everyone wants to see Nandi’s abhiṣeka and Śiva between his horns at that one hour.')]),
 glance([('Nandi','Full abhiṣeka at Pradoṣa, before the liṅga'),('Seeing','Śiva viewed between Nandi’s horns'),('Circuit','Somasūtra pradakṣiṇa: a crescent-shaped path that does not cross the water outlet'),('Procession','Śiva and Pārvatī on Nandi around the temple'),('Where strongest','Tamil Nadu and Karnataka Śiva temples'),('In Karnataka','Nañjanagūḍu, Gokarṇa, Murudeśvara and many more')],svg(560,150,'Nandi facing a liṅga',g(200,140,1.2,NANDI())+g(380,140,1.2,LING))),
 R('nandiabh','NANDI’S ABHIṢEKA','The first and greatest',svg(560,170,'Nandi being bathed by a priest with milk, curd and turmeric, crowds watching',g(280,150,1.8,NANDI())+g(180,150,1,sage('#f4f1ea'))+'<path d="M300 40 q-6 20 -10 50" stroke="#fff" stroke-width="5" fill="none"/>'+''.join(g(x,165,.5,person(c)) for x,c in [(420,'#c0392b'),(450,'#1d6fb8'),(480,'#e0a800'),(510,'#2a9d6f')])),['<b>At twilight.</b> As Pradoṣa begins, priests bathe the Nandi statue facing the sanctum with milk, curd, honey, turmeric, sandal, tender coconut and holy water, one after another.','<b>Decoration.</b> Nandi is then dressed with flowers, garlands and often a silver kavaca (cover), and lamps are waved.','<b>Why first.</b> Nandi carried the poison and was dazed by it; Śiva danced between his horns ('+L(1,'Part 2')+'). Honouring Nandi first honours that story.','<b>Offerings to Nandi.</b> Devotees bring green grass, rice and jaggery, and bilva for him.'],[('z','The bull gets a bigger bath than God?'),('b','At Pradoṣa, Nandi’s bath is the famous part. Then the Lord’s.')],'At twilight, <b>Nandi is bathed first</b>.'),
 R('horns','ŚIVA BETWEEN THE HORNS','The view from Nandi',svg(560,170,'A view past Nandi’s two horns toward the liṅga in the sanctum',g(280,170,1,'<path d="M-140 0 q0 -60 60 -80 l-10 -40 l30 30 M140 0 q0 -60 -60 -80 l10 -40 l-30 30" fill="#f4f1ea" stroke="#111" stroke-width="3"/>')+g(280,110,1.2,LING)),['<b>The view.</b> Devotees stand behind Nandi and look at the liṅga through the space between his horns: seeing Śiva as Nandi sees him, at the hour of the dance.','<b>A gesture.</b> Some touch Nandi’s horns with thumb and forefinger and look through.','<b>Whispering.</b> A popular custom is to whisper one’s prayer into Nandi’s ear, trusting him to carry it to Śiva.','<b>Not in all regions.</b> These gestures are strongest in Tamil and Karnataka temples.'],[('z','Whisper in a statue’s ear?'),('b','In Nandi’s ear. He is Śiva’s gatekeeper; devotees ask him to pass it on.')],'Śiva seen <b>between Nandi’s horns</b>.'),
 R('somasutra','THE CRESCENT PATH','Somasūtra pradakṣiṇa',svg(560,250,'A temple plan showing the special Pradoṣa circuit: from Nandi round toward the water outlet, back, and round the other way',g(280,130,.9,somasutra())),['<b>Not a full circle.</b> Normally devotees circle a shrine clockwise. At Pradoṣa many South Indian temples follow the <b>somasūtra pradakṣiṇa</b>, whose path is shaped like a crescent moon (soma).','<b>The outlet.</b> The water from Śiva’s abhiṣeka drains through a spout (gomukhī or somasūtra) on the north side. Devotees do not step across it.','<b>The pattern.</b> Starting at Nandi, one goes round to the outlet, turns back without crossing it, returns past Nandi to the other side, and so on, going back and forth, often three times. Temples teach their own exact sequence.','<b>Why.</b> Tradition says the abhiṣeka water is too sacred to cross; the back-and-forth is also linked to the gods’ panicked running to and fro around Kailāsa when the poison rose.'],[('z','So you go back and forth instead of round?'),('b','Like the gods running to and fro in their fear, until they found Śiva. Ask the temple priest for their sequence.')],'A crescent, <b>never crossing the sacred water</b>.'),
 R('procession','THE PROCESSION','Śiva and Pārvatī on Nandi',svg(560,170,'Festival images of Śiva and Pārvatī seated on a silver Nandi being carried around the temple',g(280,150,1.6,NANDI())+g(260,96,.6,SH())+g(300,96,.6,devi(items=('lotus',)))+''.join(g(x,165,.6,person('#f4f1ea')) for x in (120,160,400,440))),['<b>Pradoṣa mūrti.</b> In many Tamil and Karnataka temples the festival bronzes of Śiva and Pārvatī, seated together on Nandi (Riṣabhārūḍha), are carried around the inner corridor after the abhiṣeka.','<b>Music.</b> Nāgasvaram and drums accompany them; devotees follow.','<b>Seen at twilight.</b> The procession recreates the scene on Kailāsa: Śiva and Gaurī, with all beings gathered ('+L(3,'Part 4')+').','<b>Then the kathā.</b> Temples may read or explain the Pradoṣa story afterwards.'],[('z','They ride Nandi around the temple?'),('b','In bronze, on a decorated Nandi vāhana. It’s the high point of the evening.')],'Śiva and Pārvatī <b>ride Nandi round the temple</b>.'),
 R('karnataka','IN KARNATAKA','Where to keep Pradoṣa',svg(560,170,'A simplified map of Karnataka with Śiva temples marked',g(280,90,1,'<path d="M-80 -70 l60 -10 l40 30 l30 60 l-30 50 l-60 10 l-50 -40z" fill="#f3e3c3" stroke="#111" stroke-width="2.5"/>')+''.join(f'<circle cx="{x}" cy="{y}" r="6" fill="#c0392b" stroke="#111"/>'+lab(x+(30 if x>280 else -40),y+4,t,10) for x,y,t in [(300,130,'Nañjanagūḍu'),(220,70,'Gokarṇa'),(225,95,'Murudeśvara'),(320,60,'Śivagaṅge')])+lab(470,165,'simplified, not to scale',9)),['<b>Everywhere.</b> Almost every Śiva temple in Karnataka marks Pradoṣa, from village shrines to the great kṣetras.','<b>Nañjanagūḍu.</b> The Śrīkaṇṭheśvara temple of Nañjuṇḍa, “the one who swallowed the poison”, near Mysuru, is a natural place for Pradoṣa; see <a href="/temples-of-india/around-mysuru/nanjangud/">our article</a>.','<b>On the coast.</b> <a href="/temples-of-india/karnataka/gokarna/">Gokarṇa</a> and <a href="/temples-of-india/karnataka/murudeshwara/">Murudeśvara</a> draw crowds on Pradoṣa evenings.','<b>In Bengaluru and Mysuru.</b> City Śiva temples hold Nandi abhiṣeka at Pradoṣa; many publish their times.'],[('z','Nañjanagūḍu is the poison temple?'),('b','Nañjuṇḍa means “one who ate the poison”: the very story of Pradoṣa, in Mysuru’s backyard.')],'Karnataka’s Pradoṣa: <b>Nañjuṇḍa above all</b>.'),
 R('tamil','IN TAMIL NADU','Where Pradoṣam is a festival',svg(560,160,'A tall temple gopuram with a crowd at twilight',dusk(160)+g(280,160,1,'<path d="M-50 0 h100 l-16 -120 h-68z" fill="#e8c06a" stroke="#111" stroke-width="2"/>')+''.join(g(x,160,.5,person(c)) for x,c in [(150,'#c0392b'),(180,'#1d6fb8'),(380,'#e0a800'),(410,'#2a9d6f')])),['<b>Pradōṣam.</b> In Tamil Nadu, Pradōṣam is one of the busiest regular days in Śiva temples, with special Nandi worship, somasūtra circuits and processions.','<b>Great temples.</b> Tiruvaṇṇāmalai, Chidambaram, Madurai, Thanjavur’s great Nandi and many more draw large crowds.','<b>Tanjore Nandi.</b> The huge monolithic Nandi of the Bṛhadīśvara temple at Thanjavur receives a spectacular Pradoṣa abhiṣeka; see our <a href="/temples-of-india/tamil-nadu/thanjavur/">Thanjavur article</a>.','<b>The model.</b> Much of what Karnataka temples do at Pradoṣa follows this Tamil Śaiva pattern.'],[('z','Thanjavur’s Nandi is huge, isn’t it?'),('b','One of the largest in India, carved from a single stone. Its Pradoṣa bath is a sight.')],'Tamil Pradōṣam: <b>the great Nandis bathed</b>.'),
 R('etiquette','AT THE TEMPLE','A few customs',svg(560,150,'A devotee standing quietly behind Nandi with folded hands, footwear left outside',g(240,140,1.2,NANDI())+g(380,140,1,person('#c0392b'))),['<b>Arrive early.</b> Pradoṣa is crowded; come before sunset to see Nandi’s abhiṣeka.','<b>Do not stand between.</b> By custom, devotees avoid standing directly between Nandi and the liṅga, so as not to block Nandi’s gaze.','<b>Offerings.</b> Bring milk, bilva, flowers, or simply a lamp’s oil. Temples often prefer sealed milk packets for abhiṣeka.','<b>Follow the temple.</b> Each temple has its own order; watch, ask, and follow the priests.'],[('z','Why not stand between them?'),('b','Nandi is always gazing at Śiva. Don’t block his view.')],'Come early, <b>don’t block Nandi’s gaze</b>.'),
R('home','PRADOṢA AT HOME','When you cannot reach a temple',svg(560,150,'A home shrine at dusk with a small liṅga, a lamp and bilva leaves',dusk(150)+g(280,140,1,LING)+g(180,140,1.2,lamp())+g(380,130,1.2,bilva())),['<b>A small shrine.</b> A picture of Śiva or a small liṅga, a lamp, water, and bilva or any white flower is enough.','<b>The same order.</b> Remember Nandi (a picture or simply a bow), offer water or milk to Śiva, flowers, the lamp, and chant.','<b>The story.</b> Read the <a href="/festivals/pradosha/vrata-katha/">vrata kathā</a> aloud with the family.','<b>Online darśan.</b> Many temples stream their Pradoṣa abhiṣeka; watching with attention at the hour is a devotion too.'],[('z','Is home worship as good as the temple?'),('b','The texts praise the temple, but they praise sincerity more. Śiva is the same everywhere.')],'A lamp and water at twilight: <b>Pradoṣa at home</b>.'),
 end(i,['<b>Nandi.</b> Bathed first at twilight.','<b>Horns.</b> Śiva seen between them; prayers whispered in Nandi’s ear.','<b>Circuit.</b> Somasūtra: crescent-shaped, never crossing the outlet.','<b>Procession.</b> Śiva and Pārvatī on Nandi.','<b>Where.</b> Nañjanagūḍu, Gokarṇa, Thanjavur and every Śiva temple.'],'Part 8 follows Pradoṣa into the next night: Māsa Śivarātri.','Pradoṣa in temples'),
 sources([('Temple practice:','Wikipedia, “Pradosha” (Nandi worship in South India, procession of Śiva and Pārvatī on Nandi); popular descriptions of the somasūtra pradakṣiṇa; our temple articles.')],'the exact somasūtra sequence (varies by temple); customs like whispering to Nandi (popular).','No timings given; temples publish their own.')]
build(i,'PART 7 OF 8 · NANDI · THE CRESCENT PATH',COV,'Between Nandi’s horns','<b>Nandi’s abhiṣeka</b>, seeing Śiva <b>between the horns</b>, the <b>crescent-shaped circuit</b>, the <b>procession</b>, and Pradoṣa in Karnataka and Tamil Nadu.','Pradoṣa in temples: Nandi’s abhiṣeka, seeing Śiva between Nandi’s horns, the somasūtra pradakṣiṇa, the procession of Śiva and Pārvatī on Nandi, and Pradoṣa at Nañjanagūḍu, Gokarṇa, Murudeśvara and Tamil temples. Part 7 of the illustrated Pradoṣa series.',pp)
# ================= 8 Māsa Śivarātri
i=7
COV=covart('A Śiva liṅga at night under a thin waning crescent, devotees keeping vigil with lamps, a column of light rising faintly behind','<rect width="440" height="196" fill="#1f1a2e"/>'+g(220,190,.5,'<rect x="-14" y="-300" width="28" height="300" fill="#ff8c1a" opacity=".35"/>')+g(220,190,1.4,LING)+''.join(g(x,196,.8,person('#f4f1ea',seat=True)) for x in (90,140,300,350))+g(380,40,1,moon())+''.join(g(x,190,.7,lamp()) for x in (170,270)))
pp=[foreword(i,['The day after Pradoṣa comes Caturdaśī, the 14th. The Caturdaśī of the dark fortnight, the night before the new moon, is <b>Māsa Śivarātri</b>, “the monthly night of Śiva”. Once a year, in Māgha (Phālguna in the north), it becomes <b>Mahā Śivarātri</b>, the great night, which has its own <a href="/festivals/maha-shivaratri/">article</a>.','This part covers the monthly Śivarātri: what it is, how it is kept, its stories, and how it joins with Pradoṣa into a two-day rhythm.'],[('z','Śivarātri every month?'),('b','Every month. The great one is once a year; the monthly ones keep the flame going in between.')]),
 glance([('Name','Māsa Śivarātri, Māsik Śivarātri'),('When','Kṛṣṇa Caturdaśī (14th of the dark fortnight), every month'),('Mahā Śivarātri','The one in Māgha (amānta) / Phālguna (pūrṇimānta)'),('Practice','Fast, night worship (often in four watches), vigil, japa'),('Story','Liṅgodbhava: the column of light at midnight'),('With Pradoṣa','The dark-fortnight Pradoṣa (13th) and Śivarātri (14th) form a pair')],svg(560,140,'Two nights side by side: twilight on the 13th, midnight on the 14th',dusk(140).replace('560','280')+'<rect x="280" width="280" height="140" fill="#1f1a2e"/>'+g(140,120,1,LING)+g(420,120,1,LING)+lab(140,30,'13th: Pradoṣa')+lab(420,30,'14th: Śivarātri').replace('fill="#111"','fill="#fff"'))),
 R('what','THE MONTHLY NIGHT OF ŚIVA','Kṛṣṇa Caturdaśī',svg(560,150,'The moon waning to a thin sliver on the 14th night',''.join(f'<circle cx="{60+k*110}" cy="70" r="24" fill="#fff8d0" stroke="#111" stroke-width="1.5"/><circle cx="{60+k*110+(k+1)*9}" cy="70" r="24" fill="#1f1a2e"/>' for k in range(5))+lab(500,120,'14th: almost dark')),['<b>The darkest nights.</b> As the moon wanes to nothing, the 14th night is almost moonless. Śaivas hold this night sacred to Śiva every month.','<b>Why darkness.</b> Many teachers read it so: Śiva is the light that shines when every other light is gone.','<b>Twelve a year.</b> Every lunar month has one; with Mahā Śivarātri, the year has twelve (thirteen in a leap year).','<b>Śiva Purāṇa.</b> The Śiva Purāṇa praises the Caturdaśī night above other times for Śiva’s worship.'],[('z','So the monthly one is a small version of the big one?'),('b','The same night, the same worship, in a gentler key.')],'Every month, <b>the darkest night is Śiva’s</b>.'),
 story('lingodbhava','THE COLUMN OF LIGHT','Liṅgodbhava at midnight',strip('Three panels: Brahmā and Viṣṇu arguing; a column of fire appearing; Śiva emerging from it',[panel([(god('#c0392b'),.8),(vishnu(),.6)],'#fff3cf',140),panel([(pillar_fire(),.9)],'#1f1a2e',None),panel([(SH(),.9)],'#dfe9f6',140)],['who is greater?','the endless column','Śiva appears']),'Tradition says this happened on the Caturdaśī night.',['Brahmā and Viṣṇu argued over which of them was supreme.','A blazing column of fire appeared between them, without top or bottom.','Brahmā flew upward as a swan, Viṣṇu dug downward as a boar; neither found an end.','Śiva appeared from the fire, and they bowed to him. The Śiva Purāṇa places this <b>Liṅgodbhava</b> at midnight on Caturdaśī.','So the midnight of every Śivarātri, monthly and great, is the holiest moment. Our <a href="/festivals/kartika/karthigai-deepam/">Kārttikai Dīpam</a> article tells how the column became Aruṇācala.'],[('z','So Śivarātri is the liṅga’s birthday?'),('b','The night the endless light first showed itself as the liṅga, in that tradition.')],'At midnight, <b>the endless column of light</b>.'),
 R('keeping','KEEPING MĀSA ŚIVARĀTRI','Fast, night worship, vigil',svg(560,160,'A devotee at night before a liṅga with lamps, through four watches marked on a clock',dusk(160).replace('#e8a87c','#1f1a2e').replace('#5a5a8a','#1f1a2e')+g(200,150,1.2,LING)+g(330,150,1,person('#f4f1ea',seat=True))+''.join(f'<circle cx="{430+(k%2)*50}" cy="{50+(k//2)*50}" r="16" fill="#3a3a5a" stroke="#fff" stroke-width="2"/>'+txt(430+(k%2)*50,56+(k//2)*50,str(k+1),16,fill='#fff') for k in range(4))),['<b>Fast.</b> Many fast through the day, often a full fast or fruit and milk.','<b>Night worship.</b> Worship is done at night; some do it in four watches (yāmas), with an abhiṣeka in each, as on Mahā Śivarātri.','<b>Vigil.</b> Staying awake with “namaḥ śivāya”, hymns and stories is praised.','<b>Breaking.</b> The fast is broken the next morning, after bathing and worship.'],[('z','All night, every month?'),('b','Few manage that. Many worship at night, then sleep; the great vigil is kept for Mahā Śivarātri.')],'Fast by day, <b>worship by night</b>.'),
 R('pair','PRADOṢA AND ŚIVARĀTRI','A two-day rhythm',svg(560,150,'Two connected arcs: twilight on the 13th and midnight on the 14th',dusk(150)+'<path d="M140 120 q140 -100 280 0" fill="none" stroke="#fff" stroke-width="3" stroke-dasharray="6 4"/>'+g(140,120,1,lamp())+g(420,120,1,lamp())),['<b>Two evenings.</b> In the dark fortnight, Pradoṣa (13th, at twilight) is followed by Śivarātri (14th, at night).','<b>One vow.</b> Many devotees keep both as one observance: twilight worship on the 13th, night worship on the 14th.','<b>Then the new moon.</b> The next day is Amāvāsyā, the new moon, used in many families for offerings to ancestors (see our <a href="/festivals/pitru-paksha/">Pitṛ Pakṣa series</a>).','<b>A monthly retreat.</b> Together they make a short monthly retreat with Śiva.'],[('z','So: Ekādaśī, Pradoṣa, Śivarātri, Amāvāsyā?'),('b','The end of every dark fortnight is a little season of its own. Some keep all four.')],'Twilight on the 13th, <b>midnight on the 14th</b>.'),
 R('maha','THE GREAT ONE','How Māsa Śivarātri leads to Mahā Śivarātri',svg(560,150,'Eleven small liṅgas and one large one',''.join(g(40+k*42,120,.5,LING) for k in range(11))+g(510,130,1,LING)),['<b>Twelve steps.</b> The year’s monthly Śivarātris lead to the one great night in Māgha (Phālguna in the north), <a href="/festivals/maha-shivaratri/">Mahā Śivarātri</a>.','<b>Same worship, bigger.</b> On the great night the fast, the four watches and the all-night vigil are kept by millions, in temples and homes.','<b>Stories.</b> Mahā Śivarātri has its famous story of the hunter on the bilva tree; the monthly nights share its spirit.','<b>A year’s vow.</b> Some devotees vow to keep all twelve monthly Śivarātris, completing the vow on the great night.'],[('z','Can I start a vow of twelve?'),('b','Many begin on Mahā Śivarātri and keep the twelve that follow, ending on the next great night.')],'Twelve monthly nights, <b>one great night</b>.'),
 R('meaning','THE MEANING OF THE NIGHT','Darkness and light',svg(560,150,'A single lamp in total darkness',f'<rect width="560" height="150" fill="#111"/>'+g(280,120,2,lamp())),['<b>Rātri.</b> Night is the time of rest and dissolution. Śiva is the one into whom all things dissolve and from whom they arise again.','<b>Awake when others sleep.</b> The vigil turns night into wakefulness: the Gītā’s image of the sage awake in what is night for others (2.69).','<b>Inner light.</b> When the moon is gone, the only light is the lamp, and within, awareness itself, which is Śiva.','<b>Monthly reminder.</b> Every month the dark night returns, and with it the invitation.'],[('z','So the dark is not something to fear?'),('b','Not on Śivarātri. It’s where Śiva shines brightest.')],'When every light is gone, <b>Śiva shines</b>.'),
 R('practical','A SIMPLE MONTHLY PRACTICE','If you are starting',svg(560,140,'A small lamp, a bilva leaf and a rudrākṣa on a mat',g(160,110,1.6,lamp())+g(280,110,1.6,bilva())+g(400,100,1.6,rud())),['<b>Evening of the 13th.</b> Visit a Śiva temple at twilight, or light a lamp at home and chant “namaḥ śivāya” (Pradoṣa).','<b>Night of the 14th.</b> After dark, light a lamp, offer water and a bilva leaf, and sit for a while with the Pañcākṣara or a hymn.','<b>Eat simply</b> on both days, or fast as you can.','<b>Keep a note.</b> Mark the dates in your calendar from the pañcāṅga; the habit grows.'],[('z','That’s it?'),('b','That’s a beginning. The tradition is generous: start small and keep showing up.')],'A lamp, a leaf, <b>a name, every month</b>.'),
R('hymns','WHAT TO CHANT ON THE NIGHT','Hymns for Śivarātri',svg(560,150,'A rudrākṣa mālā and a book by a lamp at night','<rect width="560" height="150" fill="#1f1a2e"/>'+g(180,100,1.8,rud())+g(300,100,1.6,book())+g(420,110,1.4,lamp())),['<b>Pañcākṣara.</b> “Namaḥ śivāya”, as many times as you can; see our <a href="/shiva/shiva-panchakshara-stotram/">Pañcākṣara Stotram</a>.','<b>Liṅgāṣṭakam and Bilvāṣṭakam.</b> Short hymns for the liṅga and the bilva offering: <a href="/shiva/lingashtakam/">Liṅgāṣṭakam</a>, <a href="/shiva/bilvashtakam/">Bilvāṣṭakam</a>.','<b>Rudrāṣṭakam and Mahimna.</b> For longer worship: <a href="/shiva/rudrashtakam/">Rudrāṣṭakam</a>, <a href="/shiva/shiva-mahimna-stotram/">Śiva Mahimna Stotram</a>.','<b>Nirvāṇa Ṣaṭkam.</b> For the meditative midnight hour: <a href="/shiva/nirvana-shatkam/">Nirvāṇa Ṣaṭkam</a>, “I am Śiva”.'],[('z','So many hymns on the site already!'),('b','Every one of them belongs on this night. Pick one and stay with it.')],'Our Śiva hymns: <b>a night’s worth of chanting</b>.'),
 end(i,['<b>Night.</b> Kṛṣṇa Caturdaśī: the monthly Śivarātri.','<b>Story.</b> Liṅgodbhava, the endless column, at midnight.','<b>Practice.</b> Fast, night worship, vigil.','<b>Pair.</b> Pradoṣa on the 13th, Śivarātri on the 14th.','<b>Great night.</b> Twelve monthly nights lead to Mahā Śivarātri.'],'That completes the Pradoṣa series. Back to '+L(0,'Part 1')+', or to <a href="/festivals/maha-shivaratri/">Mahā Śivarātri</a>.','Māsa Śivarātri'),
 sources([('Night:','Wikipedia, “Maha Shivaratri”, “Lingodbhava”, “Shivaratri” (monthly Śivarātri on Kṛṣṇa Caturdaśī); Śiva Purāṇa, Vidyeśvara Saṃhitā (column of fire).')],'four-watch worship on monthly Śivarātris (varies); the timing of Liṅgodbhava (Purāṇic tradition).','General description.')]
build(i,'PART 8 OF 8 · THE 14TH NIGHT · THE COLUMN OF LIGHT',COV,'The monthly night of Śiva','The <b>monthly Śivarātri</b>, the <b>column of light</b>, how it is kept, the <b>two-day rhythm</b> with Pradoṣa, and the road to <b>Mahā Śivarātri</b>.','Māsa Śivarātri, the monthly night of Śiva on Kṛṣṇa Caturdaśī: Liṅgodbhava, the fast and night worship, its pairing with Pradoṣa, the path to Mahā Śivarātri, and its meaning. Part 8 of the illustrated Pradoṣa series.',pp)
